mapper.update:
UPDATE labeling_info
SET status = #{status}, updated_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT FROM labeling_info WHERE status = 'READY' AND (expires_at IS NULL OR expires_at > NOW())
AND container_main_id = #{containerMainId}
AND site_code = #{siteCode}
ORDER BY created_time DESC, id DESC LIMIT 1
